 /**
  * Legacy status adapter.
+ * Bypasses the standard transport wrapper; scope believed similar to
+ * decision 014 but dependency version was not included in this diff.
  */
 export async function getLegacyStatus(baseUrl: string): Promise<{ ok: boolean }> {
   const res = await request(`${baseUrl}/legacy/status`, {
     timeout: 2000,
   });
   return { ok: res.ok };
 }
